entries[23794] = { ["name"] = "Zanzas ewiger Glanz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Erhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 hrs lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n\"Gesegnet mit Zanzas Mojo!\"" }
entries[23795] = { ["name"] = "Zanzas ewiger Geist", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Erhöht 2 hrs lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n\"Gesegnet mit Zanzas Mojo!\"" }
