entries[23799] = { ["name"] = "Bauplan: Adamantitgewehr", ["text"] = "Benötigt Ingenieurskunst (350)\nBenutzen: Lehrt Euch die Herstellung eines Adamantitgewehrs.\nAdamantitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n126 - 234 Schaden Tempo 3.00\n(60.00 Schaden pro Sekunde)\n+12 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Stufe 69\nAnlegen: Erhöht die Angriffskraft um 22.\nBenötigt Teufelseisengehäuse (3), Adamantitrahmen (2), Eine Hand voll Teufelseisenbolzen (4)" }
entries[23800] = { ["name"] = "Bauplan: Teufelsstahlschießeisen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (360)\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschießeisens.\nTeufelsstahlschießeisen\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n104 - 194 Schaden Tempo 2.40\n(62.08 Schaden pro Sekunde)\n+12 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 13.\nBenötigt Gehärtetes Adamantitrohr , Teufelsstahlstabilisator (4), Eine Hand voll Teufelseisenbolzen (4)" }
entries[23801] = { ["name"] = "Schlüssel der Sichelklauen", ["text"] = "Questgegenstand\nBenutzen: Öffnet Käfige der Sichelklauen." }
entries[23802] = { ["name"] = "Bauplan: Verschnörkeltes Khoriumgewehr", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Lehrt Euch die Herstellung eines verschnörkelten Khoriumgewehrs.\nVerschnörkeltes Khoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n144 - 268 Schaden Tempo 3.10\n(66.45 Schaden pro Sekunde)\n+14 Beweglichkeit\nHaltbarkeit 75 / 75\nBenötigt Stufe 70\nAnlegen: Erhöht die Trefferwertung um 13.\nBenötigt Gehärtetes Adamantitrohr (2), Khoriumbarren (12), Eine Hand voll Teufelseisenbolzen (4), Edeltopas (2)" }
entries[23803] = { ["name"] = "Bauplan: Zahnradbrille", ["text"] = "Benötigt Ingenieurskunst (340)\nBenutzen: Lehrt Euch die Herstellung einer Zahnradbrille.\nZahnradbrille\nWird beim Anlegen gebunden\nKopf Leder\n220 Rüstung\n<Zufällige Verzauberung>\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (340)\nBenötigt Schweres Knotenhautleder (4), Blutgranat (2), Arkaner Staub (8)" }
entries[23804] = { ["name"] = "Bauplan: Energieverstärkungsbrille", ["text"] = "Benötigt Ingenieurskunst (340)\nBenutzen: Lehrt Euch die Herstellung einer Energieverstärkungsbrille.\nEnergieverstärkungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n100 Rüstung\n+46 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (340)\nAnlegen: Erhöht die kritische Trefferwertung um 31.\nAnlegen: Erhöht die Zaubermacht um 36.\nBenötigt Schweres Knotenhautleder (4), Flammenspessarit (2), Arkaner Staub (8)" }
entries[23805] = { ["name"] = "Bauplan: Ultraspektropische Enthüllungsbrille", ["text"] = "Benötigt Ingenieurskunst (350)\nBenutzen: Lehrt Euch die Herstellung einer ultraspektropischen Enthüllungsbrille.\nUltraspektropische Enthüllungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n124 Rüstung\n+36 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (350)\nAnlegen: Erhöht die kritische Trefferwertung um 24.\nAnlegen: Erhöht die Trefferwertung um 24.\nAnlegen: Erhöht Eure Abhärtungswertung um 24.\nAnlegen: Erhöht die Tempowertung um 24.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Schweres Knotenhautleder (4), Khoriumbarren (2), Tiefenperidot (2), Kleiner Prismasplitter (2)" }
entries[23806] = { ["name"] = "Bauplan: Extremsichtbrille", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (360)\nBenutzen: Lehrt Euch die Herstellung einer Extremsichtbrille.\nExtremsichtbrille\nWird beim Anlegen gebunden\nKopf Leder\n232 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (360)\nAnlegen: Erhöht die Trefferwertung um 23.\nAnlegen: Erhöht die Angriffskraft um 84.\nBenutzen: Erhöht 15 sec lang Eure Verstohlenheitsentdeckung. (2 Min Abklingzeit)\nBenötigt Schweres Knotenhautleder (4), Khoriumbarren (2), Nachtauge (2), Großer Prismasplitter (2)" }
entries[23807] = { ["name"] = "Bauplan: Adamantitzielfernrohr", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines Adamantitzielfernrohrs.\nAdamantitzielfernrohr\nBenötigt Stufe 55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 10.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nBenötigt Adamantitbarren (8), Golddraenit (2)" }
entries[23808] = { ["name"] = "Bauplan: Khoriumzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (360)\nBenutzen: Lehrt Euch die Herstellung eines Khoriumzielfernrohrs.\nKhoriumzielfernrohr\nBenötigt Stufe 55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 12.\nBenötigt Gehärtetes Adamantitrohr , Khoriumbarren (4), Dämmerstein (2)" }
entries[23809] = { ["name"] = "Bauplan: Geeichtes Eterniumzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (375)\nBenutzen: Lehrt Euch die Herstellung eines geeichten Eterniumzielfernrohrs.\nGeeichtes Eterniumzielfernrohr\nBenötigt Stufe 60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht die kritische Trefferwertung dieser Waffe um 28.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nBenötigt Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (6), Stern der Elune (2)" }
entries[23810] = { ["name"] = "Bauplan: Krachbummroboter", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Krachbummroboters.\nKrachbummroboter\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)\nBenötigt Adamantitrahmen , Teufelseisengehäuse (2), Goldkraftkern , Eine Hand voll Teufelseisenbolzen (2)" }
entries[23811] = { ["name"] = "Bauplan: Weißes Rauchsignal", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines weißen Rauchsignals.\nWeißes Rauchsignal\nBenutzen: Wirft ein weißes Rauchsignal in ein bestimmtes Gebiet. Hält 5 min lang an. (5 Sek. Abklingzeit)\nBenötigt Elementarsprengpulver , Netherstoff" }
entries[23812] = { ["name"] = "Bauplan: Rotes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines roten Rauchsignals.\nRotes Rauchsignal\nBenutzen: Wirft ein rotes Rauchsignal in ein bestimmtes Gebiet. Hält 5 min lang an. (5 Sek. Abklingzeit)\nBenötigt Elementarsprengpulver , Netherstoff , Roter Farbstoff" }
entries[23813] = { ["name"] = "Bauplan: Blaues Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines blauen Rauchsignals.\nBlaues Rauchsignal\nBenutzen: Wirft ein blaues Rauchsignal in ein bestimmtes Gebiet. Hält 5 min lang an. (5 Sek. Abklingzeit)\nBenötigt Elementarsprengpulver , Netherstoff , Blauer Farbstoff" }
entries[23814] = { ["name"] = "Bauplan: Grünes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenötigt Expedition des Cenarius\n- Freundlich\nBenutzen: Lehrt Euch die Herstellung eines grünen Rauchsignals.\nGrünes Rauchsignal\nBenutzen: Wirft ein grünes Rauchsignal in ein bestimmtes Gebiet. Hält 5 min lang an. (5 Sek. Abklingzeit)\nBenötigt Elementarsprengpulver , Netherstoff , Grüner Farbstoff" }
entries[23815] = { ["name"] = "Bauplan: Maschine für Adamantitpatronen", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung einer Maschine für Adamantitpatronen.\nMaschine für Adamantitpatronen\nBenutzen: Stellt 200 Adamantitpatronen her.\n5 Aufladungen\n\"Warnung: Enthält Sprengstoff.\"\nBenötigt Adamantitbarren , Elementarsprengpulver (2), Einfaches Holz (4)" }
entries[23816] = { ["name"] = "Bauplan: Werkzeugkasten aus Teufelseisen", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Teufelseisen.\nWerkzeugkasten aus Teufelseisen\nWird beim Anlegen gebunden\n24 Platz Ingenieurstasche\nBenötigt Teufelseisengehäuse , Teufelseisenbarren (5), Eine Hand voll Teufelseisenbolzen (2)" }
entries[23817] = { ["name"] = "Bauplan: Werkzeugkasten aus Titan", ["text"] = "Benötigt Ingenieurskunst (405)\nBenutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Titan.\nWerkzeugkasten aus Titan\nWird beim Anlegen gebunden\n32 Platz Ingenieurstasche\n\"Unterteilt in kleine Fächer, die sich perfekt für die Aufbewahrung von Ingenieursbedarf eignen.\"\nBenötigt Saronitbarren (8), Titanbarren (8), Eine Hand voll Kobaltbolzen (4)" }
entries[23818] = { ["name"] = "Übersetzungsfibel der Tannenruhfeste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, die Symbole der Furbolgs der Tannenruhfeste besser zu verstehen.\n\"Die Fibel enthält Übersetzungen für die Grundsymbole aus der Furbolgsprache.\"" }
entries[23819] = { ["name"] = "Elementare Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (350)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf." }
entries[23820] = { ["name"] = "Tiervergrößerer", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Vergrößert ein Tier auf das Doppelte. (15 Sek. Abklingzeit)\n\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"" }
entries[23821] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Einzigartig\nBenötigt Ingenieurskunst (305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet." }
entries[23822] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"" }
entries[23823] = { ["name"] = "Manatrankeinspritzung", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"" }
entries[23824] = { ["name"] = "Raketenstiefel Xtrem", ["text"] = "Wird beim Anlegen gebunden\nFüße Leder\n196 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (330)\nAnlegen: Erhöht die Angriffskraft um 80.\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)" }
entries[23825] = { ["name"] = "Gürtel der fast perfekten Unverwundbarkeit", ["text"] = "Wird beim Anlegen gebunden\nTaille Stoff\n223 Rüstung\n+21 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Ingenieurskunst (350)\nBenutzen: Schützt Euch mit einem Energieschild, das 8 sec lang 4000 Schaden aufhält. (5 Min Abklingzeit)\n\"Der Schutz ist nicht immer wirksam. In SELTENEN Fällen kann der Träger zusätzlichen Schaden erleiden.\"" }
entries[23826] = { ["name"] = "Der Größere", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Fügt 600 to 1000 Feuerschaden zu und macht Ziele in einem Radius von 10 Metern 5 sec lang bewegungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 80. (1 Min Abklingzeit)" }
entries[23827] = { ["name"] = "Super Pioniersprengladung", ["text"] = "Benötigt Ingenieurskunst (340)\nBenutzen: Explodiert bei Zündung, verursacht 900 to 1500 Feuerschaden an allen in der Nähe befindlichen feindlichen Einheiten und an Euch 675 to 1125 Schaden. (5 Min Abklingzeit)" }
entries[23828] = { ["name"] = "Gnomische Machtschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n132 Rüstung\n+21 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (375)\nBenötigt Gnomeningenieur\nAnlegen: Erhöht die Zaubermacht um 59.\nAnlegen: Erhöht Eure kritische Trefferwertung um 28." }
entries[23829] = { ["name"] = "Gnomische Kampfschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n249 Rüstung\n+21 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst (375)\nBenötigt Gnomeningenieur\nAnlegen: Erhöht die Angriffskraft um 100.\nAnlegen: Erhöht Eure kritische Trefferwertung um 28." }
entries[23830] = { ["name"] = "Kloppers Ausrüstung", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Ausrüstung scheint in Ordnung zu sein.\"" }
entries[23831] = { ["name"] = "Goblindampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen" }
entries[23832] = { ["name"] = "Gnomische Dampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen" }
entries[23833] = { ["name"] = "Kunstloses Murlocmesser", ["text"] = "Questgegenstand\n\"Eine grob behauene Steinklinge an einem langen Stab mit einer Sehne.\"" }
entries[23834] = { ["name"] = "Kunstloser Murlocgötze", ["text"] = "Questgegenstand\n\"Ein grob geschnitzter Götze, der keine erkennbare Figur darstellt.\"" }
entries[23835] = { ["name"] = "Gnomischer Geflügelisierer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst (340)\nBenötigt Gnomeningenieur\nBenutzen: Verwandelt den Gegner 15 sec lang in ein Huhn. Das heißt, falls die Transmogrifikationspolarität nicht verwechselt wurde... (5 Min Abklingzeit)" }
entries[23836] = { ["name"] = "Goblinraketenwerfer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nBenutzen: Feuert eine mächtige Rakete auf den Gegner, die 960 to 1440 Schaden verursacht und ihn 3 Sek. lang betäubt. Das Ding hat aber einen ziemlichen Rückstoß... (2 Min Abklingzeit)" }
entries[23837] = { ["name"] = "Verwitterte Schatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 13\n\"Das Pergament ist vergilbt, verblichen und voller Löcher, dennoch ist das Meiste noch lesbar.\"" }
entries[23838] = { ["name"] = "Verzauberter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n132 Rüstung\n+48 Ausdauer\n+30 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nAnlegen: +10% Betäubungswiderstand.\nAnlegen: Erhöht die Zaubermacht um 36." }
entries[23839] = { ["name"] = "Verstärkter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n550 Rüstung\n+30 Beweglichkeit\n+48 Ausdauer\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nAnlegen: Erhöht die Angriffskraft um 62.\nAnlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%." }
entries[23840] = { ["name"] = "Tragbarer Briefkasten", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Entfaltet einen tragbaren Briefkasten, mit dem man Briefe schicken und empfangen kann. Seine Energie reicht 5 min lang." }
entries[23841] = { ["name"] = "Gnomisches Flammengeschütz", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Errichtet schnell ein gnomisches Flammengeschütz zu Euren Füßen, das automatisch angreifen wird. Meistens Gegner. Das Geschütz fällt nach 45 sec in sich zusammen. (1 Min Abklingzeit)" }
entries[23843] = { ["name"] = "Luftwirbel", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Teil von Susurrus, der auf irgendeine Weise an Eure Hand gebunden bleibt.\"" }
entries[23844] = { ["name"] = "Nolkais Laterne", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz" }
entries[23845] = { ["name"] = "Felshetzerbalg", ["text"] = "Questgegenstand" }
entries[23846] = { ["name"] = "Nolkais Kasten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[23847] = { ["name"] = "Nolkais Band", ["text"] = "\"Auf der Innenseite des Bands befindet sich eine Inschrift: Ein Erinnerungsstück von mir für meine Liebe. Möge Elune über meinen geliebten Nolkai wachen.\"" }
entries[23848] = { ["name"] = "Nethergarde Bitter", ["text"] = "Benötigt Stufe 30\nBenutzen: Ein extrem starkes alkoholisches Getränk." }
entries[23849] = { ["name"] = "Tannenruhgetreide", ["text"] = "Questgegenstand" }
entries[23850] = { ["name"] = "Gurfs Würde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 7\n\"Ein kleines Stück weißes Fell, das Gurf von der Tannenruhfeste gehört.\"" }
entries[23851] = { ["name"] = "Zerfleddertes Tagebuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Einband des Tagebuchs ist zerfleddert und die Seiten sind vergilbt; nur zwei der Einträge sind noch lesbar.\"" }
entries[23852] = { ["name"] = "Nolkais Tasche", ["text"] = "Wird beim Aufheben gebunden\n8 Platz Behälter\n\"Die Tasche war zwar einige Zeit in der Erde vergraben, der Zustand scheint jedoch fast wie neu.\"" }
