entries[23857] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, Eure Rüstung und Euren Magiewiderstand zu erhöhen, wenn Ihr im Gefecht getroffen werdet. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23858] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Vermächtnis des Bergkönigs' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>" }
entries[23859] = { ["name"] = "Glyphe vom Monument der Nazzivus", ["text"] = "Questgegenstand\nEinzigartig\n\"Finster aussehende Kreaturen in Begleitung einiger humanoider Gestalten bilden zusammen eine Art Erzählung.\"" }
entries[23860] = { ["name"] = "Kurkens Balg", ["text"] = "Questgegenstand\nEinzigartig" }
entries[23861] = { ["name"] = "Abschriftenset", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erschafft einen Abdruck des Monuments der Satyre von Nazzivus.\n\"Ein tragbares Abschriftenset zum Anfertigen einfacher Zeichnungen und Abpausbilder.\"" }
entries[23862] = { ["name"] = "Erlösung des Gefallenen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren Heilzaubern eine Chance, einen geisterhaften Verbündeten zu beschwören. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23863] = { ["name"] = "Verderbter Kristall", ["text"] = "Questgegenstand\n\"Der Kristall pulsiert in einem aggressiven Rot. Man kann kaum glauben, dass dies einmal ein Teil der Exodar war.\"" }
entries[23864] = { ["name"] = "Qual des Worgen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, bei Nahkampf- und Distanzangriffen zusätzlichen Schattenschaden zu verursachen.\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23865] = { ["name"] = "Zorn der Titanen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren offensiven Zaubern eine Chance, zusätzlichen Schaden zuzufügen. (Procchance: 3%, 30s Abklingzeit)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23866] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Erlösung des Gefallenen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>" }
entries[23867] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Zorn der Titanen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>" }
entries[23868] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Qual des Worgen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>" }
entries[23869] = { ["name"] = "Kristallisierte Rinde", ["text"] = "Questgegenstand\n\"Splitter von roten Kristallen haben sich in der Rinde festgesetzt und ersetzen teilweise das Holz.\"" }
entries[23870] = { ["name"] = "Roter Kristallanhänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 9\n\"Ein Schmuckstück, das aus einem Kristallsplitter und einer gerollten Seetangkordel hergestellt wurde.\"" }
entries[23871] = { ["name"] = "Trank der Wasseratmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\nBenötigt Stufe 8\nBenutzen: Der Anwender kann 30 min lang unter Wasser atmen. (3 Sek. Abklingzeit)" }
entries[23872] = { ["name"] = "Blauer Ranzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[23873] = { ["name"] = "Galaens Amulett", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein kleiner, mit Juwelen besetzter Anhänger ist am Ende einer dünnen Kette befestigt.\"" }
entries[23874] = { ["name"] = "Bauplan: Elementare Zephyriumladung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (350)\nBenötigt Das Konsortium\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer elementaren Zephyriumladung.\nElementare Zephyriumladung\nBenötigt Ingenieurskunst (350)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf.\nBenötigt Elementarsprengpulver (2), Teufelseisengehäuse , Eine Hand voll Teufelseisenbolzen" }
entries[23875] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt eine Probe des Kristalls zwischen den Trümmern des Absturzes." }
entries[23876] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt einen Splitter eines Kristalls, der von den Blutelfen benutzt wird." }
entries[23877] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt einen Splitter eines Kristalls in der Nazzuviussiedlung Axxarien." }
entries[23878] = { ["name"] = "Kristallprobe der Absturzstelle", ["text"] = "Einzigartig\n\"Ein Kristallbruchstück von den Trümmern der Exodar.\"" }
entries[23879] = { ["name"] = "Veränderte Kristallprobe", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Kristallsplitter war einst ein Teil der Exodar, wurde aber von den Blutelfen verändert.\"" }
entries[23880] = { ["name"] = "Axxarienkristallprobe", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Probe der Kristalle aus den Siedlungen der Satyrn.\"" }
entries[23881] = { ["name"] = "Gargolmars Hand", ["text"] = "Questgegenstand\nEinzigartig" }
entries[23882] = { ["name"] = "Bauplan: Tiervergrößerer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Tiervergrößerers.\nTiervergrößerer\nBenötigt Ingenieurskunst (325)\nBenutzen: Vergrößert ein Tier auf das Doppelte. (15 Sek. Abklingzeit)\n\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"\nBenötigt Adamantitrahmen , Eine Hand voll Teufelseisenbolzen (2), Goldkraftkern" }
entries[23883] = { ["name"] = "Bauplan: Heiltrankeinspritzung", ["text"] = "Benötigt Ingenieurskunst (330)\nBenutzen: Lehrt Euch die Herstellung einer Heiltrankeinspritzung.\nHeiltrankeinspritzung\nBenötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nBenötigt Teufelseisengehäuse , Eine Hand voll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Heiltrank (20)" }
entries[23884] = { ["name"] = "Bauplan: Manatrankeinspritzung", ["text"] = "Benötigt Ingenieurskunst (345)\nBenutzen: Lehrt Euch die Herstellung einer Manatrankeinspritzung.\nManatrankeinspritzung\nBenötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nBenötigt Teufelseisengehäuse , Eine Hand voll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Manatrank (20)" }
entries[23885] = { ["name"] = "Bauplan: Tragbarer Briefkasten", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines tragbaren Briefkastens.\nTragbarer Briefkasten\nBenötigt Ingenieurskunst (335)\nBenutzen: Entfaltet einen tragbaren Briefkasten, mit dem man Briefe schicken und empfangen kann. Seine Energie reicht 5 min lang.\nBenötigt Adamantitrahmen , Eine Hand voll Teufelseisenbolzen (2), Khoriumkraftkern , Verschmorte Verkabelung" }
entries[23886] = { ["name"] = "Omors Huf", ["text"] = "Questgegenstand\nEinzigartig" }
entries[23887] = { ["name"] = "Bauplan: Raketenstiefel Xtrem", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (355)\nBenutzen: Lehrt Euch die Herstellung von Raketenstiefeln Xtrem.\nRaketenstiefel Xtrem\nWird beim Anlegen gebunden\nFüße Leder\n196 Rüstung\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (330)\nAnlegen: Erhöht die Angriffskraft um 80.\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)\nBenötigt Schweres Knotenhautleder (8), Khoriumkraftkern (2), Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (4)" }
entries[23888] = { ["name"] = "Bauplan: Schockdrosselnder Partikelextraktor", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (305)\nBenutzen: Lehrt Euch die Herstellung eines schockdrosselnden Partikelextraktors.\nSchockdrosselnder Partikelextraktor\nEinzigartig\nBenötigt Ingenieurskunst (305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet.\nBenötigt Teufelseisengehäuse (2), Eine Hand voll Teufelseisenbolzen (2), Urleben (4), Empfindlicher Arkanitwandler" }
