entries[23898] = { ["name"] = "Zähmertotem", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beginnt mit der Zähmung eines Nachtpirschers, damit er 15 min lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl.\n3 Aufladungen" }
