entries[24000] = { ["name"] = "Formel: Armschiene - Überragende Heilung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (325)\nBenötigt Thrallmar\n- Freundlich\nBenutzen: Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass sie die Zaubermacht um 15 erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nArmschienen dauerhaft verzaubern, sodass die Zaubermacht um 15 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher." }
entries[24001] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(330)\nBenötigt Thrallmar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 hour lang die Beweglichkeit um 30 und die kritische Trefferwertung um 12. Kampfelixier. (3 Sek. Abklingzeit)\nBenötigt Terozapfen , Teufelsgras (2), Magieerfüllte Phiole" }
entries[24002] = { ["name"] = "Pläne: Teufelsstahlschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (360)\nBenötigt Thrallmar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschildstachels.\nTeufelsstahlschildstachel\nBenutzen: Bringt einen Teufelsstahlstachel an Eurem Schild an, der bei jedem Blocken 26-38 Schaden verursacht.\nBenötigt Teufelsstahlbarren (4), Urfeuer (4), Urerde (4)" }
entries[24003] = { ["name"] = "Formel: Brust - Außergewöhnliche Werte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (345)\nBenötigt Thrallmar\n- Respektvoll\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft zu verzaubern, sodass sie alle Werte um 6 erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Brustrüstung dauerhaft verzaubern, sodass alle Werte um 6 erhöht werden. Erfordert einen Gegenstand der Stufe 35 oder höher." }
