entries[24167] = { ["name"] = "Vorlage: Lebendiger Rubinanhänger", ["text"] = "Benötigt Juwelenschleifen (355)\nBenutzen: Lehrt Euch die Herstellung eines lebendigen Rubinanhängers.\nLebendiger Rubinanhänger\nWird beim Anlegen gebunden\nHals\n+24 Ausdauer\n+15 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubermacht um 19.\nAnlegen: Stellt alle 5 Sek. 8 Mana wieder her.\nBenutzen: Stellt 30 min lang pro Sekunde 6 Gesundheit aller in der Nähe befindlichen Gruppenmitglieder wieder her. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Khoriumbarren (4), Quecksilberadamantit , Lebendiger Rubin" }
entries[24168] = { ["name"] = "Vorlage: Geflochtene Eterniumkette", ["text"] = "Benötigt Juwelenschleifen (360)\nBenutzen: Lehrt Euch die Herstellung einer geflochtenen Eterniumkette.\nGeflochtene Eterniumkette\nWird beim Anlegen gebunden\nHals\nBenötigt Stufe 70\nAnlegen: Erhöht die Trefferwertung um 21.\nAnlegen: +5 Waffenschaden.\nBenutzen: Erhöht die kritische Trefferwertung naher Gruppenmitglieder 30 min lang um 28. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Eterniumbarren (2), Quecksilberadamantit (3)" }
entries[24169] = { ["name"] = "Vorlage: Auge der Nacht", ["text"] = "Benötigt Juwelenschleifen (360)\nBenutzen: Lehrt Euch die Herstellung eines Auges der Nacht.\nAuge der Nacht\nWird beim Anlegen gebunden\nHals\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 26.\nAnlegen: Erhöht die Trefferwertung um 16.\nAnlegen: Erhöht Eure Zauberdurchschlagskraft um 15.\nBenutzen: Erhöht die Zaubermacht aller in der Nähe befindlichen Gruppenmitglieder 30 min lang um 34. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Gehärteter Adamantitbarren (2), Quecksilberadamantit (2), Nachtauge" }
entries[24170] = { ["name"] = "Vorlage: Zärtliche Morgenröte", ["text"] = "Benötigt Juwelenschleifen (365)\nBenutzen: Lehrt Euch die Herstellung einer zärtlichen Morgenröte.\nZärtliche Morgenröte\nWird beim Anlegen gebunden\nHals\n+27 Ausdauer\n+19 Intelligenz\nBenötigt Stufe 70\nAnlegen: Stellt alle 5 Sek. 9 Mana wieder her.\nBenutzen: Alle Werte naher Gruppenmitglieder werden 30 min lang um 10 erhöht. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Eterniumbarren (2), Quecksilberadamantit (4), Golddraenit (2)" }
entries[24171] = { ["name"] = "Vorlage: Kette der Nebeleule", ["text"] = "Benötigt Juwelenschleifen (365)\nBenutzen: Lehrt Euch die Herstellung einer Kette der Nebeleule.\nKette der Nebeleule\nWird beim Anlegen gebunden\nHals\n+19 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht die Verteidigungswertung um 18.\nAnlegen: Erhöht die Zaubermacht um 21.\nBenutzen: Erhöht die kritische Trefferwertung naher Gruppenmitglieder 30 min lang um 45. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Khoriumbarren (2), Quecksilberadamantit (4), Azurmondstein (2)" }
entries[24172] = { ["name"] = "Vorlage: Kronenreif der grünen Flamme", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (370)\nBenutzen: Lehrt Euch die Herstellung eines Kronenreifs der grünen Flamme.\nKronenreif der grünen Flamme\nWird beim Anlegen gebunden\nKopf Stoff\n138 Rüstung\n+36 Ausdauer\n+40 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 70\nAnlegen: Chance bei erfolgreichem Zauberwirken im Verlauf von 10 sec 90 Mana wiederherzustellen. (Procchance: 75%, 25s Abklingzeit)\nBenötigt Khoriumbarren (20), Urleben (20), Talasit (2), Quecksilberadamantit (5)" }
entries[24173] = { ["name"] = "Vorlage: Reif der arkanen Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (370)\nBenutzen: Lehrt Euch die Herstellung eines Reifs der arkanen Macht.\nReif der arkanen Macht\nWird beim Anlegen gebunden\nKopf Stoff\n138 Rüstung\n+39 Ausdauer\n+27 Intelligenz\n+27 Willenskraft\nHaltbarkeit 60 / 60\nBenötigt Stufe 70\nAnlegen: Chance von 2%, bei erfolgreichem Zauberwirken die Zaubermacht 15 sec lang um bis zu 120 zu erhöhen. (Procchance: 2%)\nBenötigt Teufelsstahlbarren (20), Urmana (20), Stern der Elune (2), Quecksilberadamantit (5)" }
entries[24174] = { ["name"] = "Vorlage: Anhänger der Eisflamme", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (360)\nBenötigt Hüter der Zeit\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Anhängers der Eisflamme.\nAnhänger der Eisflamme\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Feuerwiderstand\nBenötigt Stufe 70\nBenutzen: Absorbiert 900 to 2700 Feuerschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 min lang an. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Teufelsstahlbarren (2), Urwasser (6), Urfeuer (4), Quecksilberadamantit" }
entries[24175] = { ["name"] = "Vorlage: Anhänger des Tauens", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (360)\nBenötigt Unteres Viertel\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Anhängers des Tauens.\nAnhänger des Tauens\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Frostwiderstand\nBenötigt Stufe 70\nBenutzen: Absorbiert von allen nahen Gruppenmitgliedern 900 to 2700 Frostschaden. Hält 5 min lang an. (1 Stunde Abklingzeit)\n10 AufladungenBenötigt Teufelsstahlbarren (2), Urfeuer (6), Urwasser (4), Quecksilberadamantit" }
